insert into public.spotlights
  (type, month, status, name, discogs_id, subtitle, meta, bio, releases, collector_notes, neighbors, rekoodos_pick)
values
(
  'label',
  '2026-10',
  'draft',
  '4AD',
  '4AD_DISCOGS_ID',
  'London independent label founded in 1980 by Ivo Watts-Russell and Peter Kent, initially a subsidiary of Beggars Banquet. The visual identity created by designer Vaughan Oliver from 1982 onwards became as central to the label''s catalogue as any of its recordings.',
  $json${"founded": "1980", "location": "London, UK", "website": "4ad.com"}$json$,
  $json$[
    "4AD was founded in London in 1980 by Ivo Watts-Russell and Peter Kent as a subsidiary of Beggars Banquet. The label operated briefly under the name Axis before adopting its permanent name. Bauhaus released material through the imprint in its early period, and The Birthday Party, Nick Cave's pre-Bad Seeds group, recorded for 4AD during their time in London in the early 1980s. Vaughan Oliver, later working under the name v23, began designing artwork for the label in 1982 and continued for nearly two decades, producing sleeves characterised by textured photography, layered typography, and imagery that resisted immediate interpretation.",
    "The Cocteau Twins signed to 4AD in 1982 and became its most continuous presence across the decade, releasing a sequence of albums and EPs that moved from post-punk guitar to a more processed and layered approach. Guitarist Robin Guthrie's heavily layered production and vocalist Elizabeth Fraser's use of voice as tonal and rhythmic material rather than conventional singing were central to the label's identity throughout the period. Dead Can Dance signed in 1983 and took the label in a different direction, drawing on acoustic instrumentation and a wider range of historical and geographical influence than most guitar-based music of the period. Watts-Russell's own project, This Mortal Coil, assembled rotating 4AD artists around interpretations of songs by Tim Buckley, Big Star, and others; it functioned as a direct expression of what the label's internal aesthetic was in its purest form.",
    "Throwing Muses signed to 4AD in 1985, becoming the first American band on the label, and their self-titled debut in 1986 brought a noisier and more rhythmically assertive sound to the catalogue. The Pixies followed in 1987; Surfer Rosa, their debut full-length, was recorded in 1988 by Steve Albini and remains the most commercially prominent record in the 4AD catalogue. Doolittle followed in 1989, produced by Gil Norton. Through the first half of the 1990s, The Breeders, Belly, and Lush extended the label's reach, each working in different positions within the post-Pixies guitar-pop landscape.",
    "Watts-Russell sold his stake in the label to Beggars Banquet in 1999, ending his involvement after nearly two decades. 4AD continued as part of the Beggars Group and rebuilt its roster: St. Vincent, Feist, Grimes, Daughter, Big Thief, and Julia Jacklin are among the artists whose work has appeared on 4AD since 2000. The physical quality of pressings remained consistently high through the transition, and the label's back catalogue has been reissued on a rolling basis, though the quality of original Vaughan Oliver packaging has rarely been matched in those reissues."
  ]$json$,
  $json$[
    {
      "year": "1984",
      "title": "It'll End in Tears",
      "artist": "This Mortal Coil",
      "badge": "Studio Collective",
      "note": "Watts-Russell's studio collective made its first record by gathering 4AD artists around cover versions of songs by Tim Buckley, Big Star, and Talking Heads. The cover of Song to the Siren, with Elizabeth Fraser on vocals, became the most widely known recording from the 4AD catalogue outside its core fanbase. The record is less a band album than a document of what the label's internal aesthetic was when applied directly to existing material."
    },
    {
      "year": "1990",
      "title": "Heaven or Las Vegas",
      "artist": "Cocteau Twins",
      "badge": null,
      "note": "The Cocteau Twins' sixth album and the point at which the elements they had developed across the decade resolved most completely. Guthrie's production is warmer and more detailed than on earlier records, and Fraser's vocals sit more prominently in the mix. The Vaughan Oliver sleeve for the original 4AD pressing is among his more restrained designs, which in context makes it among his most effective."
    },
    {
      "year": "1987",
      "title": "Within the Realm of a Dying Sun",
      "artist": "Dead Can Dance",
      "badge": null,
      "note": "Third album, and the one that pushed furthest from the post-punk of their debut into orchestral and acoustic territory. Lisa Gerrard's voice takes on a more operatic character than on the first two records, and Brendan Perry's arrangements are larger in scale. Original 4AD pressings carry the full Vaughan Oliver sleeve; reissues have not consistently reproduced it to the same standard."
    },
    {
      "year": "1988",
      "title": "Surfer Rosa",
      "artist": "Pixies",
      "badge": "Steve Albini",
      "note": "The Pixies' debut full-length, recorded by Steve Albini in Boston. Albini's recording method places the drums prominently and captures the room without significant processing, giving the record a directness that later Pixies productions moved away from. The original 4AD pressing is the reference and appears on the secondary market with reasonable frequency."
    },
    {
      "year": "1986",
      "title": "Throwing Muses",
      "artist": "Throwing Muses",
      "badge": "First US Signing",
      "note": "4AD's first American signing, produced by Gil Norton. Tanya Donelly and Kristin Hersh's interlocking guitar lines and the irregular metre shifts that characterise several arrangements made this an unusual record in the label's catalogue at the time. The US Sire pressing carries different artwork from the 4AD original; collectors wanting the 4AD version should verify the pressing before buying."
    },
    {
      "year": "1992",
      "title": "Spooky",
      "artist": "Lush",
      "badge": null,
      "note": "Lush's first proper studio album, produced by Robin Guthrie of the Cocteau Twins. Guthrie applies the layering approach he developed with the Cocteau Twins: guitars close to the surface, vocals blended into the texture, slow harmonic development. Miki Berenyi and Emma Anderson's vocal interplay was directly influenced by Fraser's technique, though the songwriting structure is more verse-chorus than the Cocteau Twins' work."
    }
  ]$json$,
  $json$[
    {
      "title": "Original Pressings vs. Reissues",
      "body": "Original pressings from the Watts-Russell era carry CAD catalogue numbers, which run sequentially and allow collectors to identify first pressings. Vaughan Oliver's sleeve work was printed to a consistently high standard: textured or coated board stock, inner sleeves with additional imagery, and photographic reproduction that later reissues have rarely matched. For records like Heaven or Las Vegas, It'll End in Tears, and Within the Realm of a Dying Sun, the original sleeve is a central part of the object's value rather than incidental to the music. Reissues from the mid-2000s onward are often identifiable by flatter print quality and the absence or simplification of the original inner sleeve material."
    },
    {
      "title": "Collecting Strategy",
      "body": "The most accessible entry point to the catalogue is Surfer Rosa, which appears regularly on the secondary market in reasonable condition at accessible prices. The records that reward the most attention in terms of original pressing quality are the Cocteau Twins, This Mortal Coil, and Dead Can Dance titles: original CAD pressings for these are among the best examples of Vaughan Oliver's work and are worth seeking over reissues. The Throwing Muses self-titled debut has a meaningful difference between the original 4AD pressing and the American Sire issue; collectors wanting the 4AD version should verify the catalogue number before buying. For the This Mortal Coil albums, original CAD pressings with intact inner sleeves are increasingly difficult to find in good condition, and condition matters more for these than for most other titles in the catalogue."
    }
  ]$json$,
  $json$[
    {
      "tag": "Sonic Neighbour",
      "artist": "My Bloody Valentine",
      "album": "Loveless (1991)",
      "reason": "My Bloody Valentine released on Creation Records rather than 4AD, but Loveless occupied the same sonic territory as Lush and the later Cocteau Twins records: heavily processed guitar, layered vocals used as texture, abstract production built on studio technique. The collector who works through the Lush and Cocteau Twins catalogues will find Loveless a direct adjacent object. The two labels' rosters overlapped in aesthetic intention throughout the late 1980s and early 1990s without sharing personnel."
    },
    {
      "tag": "Sonic Neighbour",
      "artist": "Slowdive",
      "album": "Souvlaki (1993)",
      "reason": "Slowdive released on Creation Records, not 4AD, but Souvlaki was produced partly with Brian Eno and uses slow tempos, heavily reverbed guitars, and vocals mixed as texture in a way directly comparable to the approach of Lush's Spooky and the Cocteau Twins' late-period records. A collector moving through 4AD's early-1990s output will find Slowdive an adjacent and complementary body of work."
    },
    {
      "tag": "Label Context",
      "artist": "Robin Guthrie",
      "album": "Imperial (2006)",
      "reason": "Guthrie left the Cocteau Twins in 1997 and has released a substantial catalogue of solo instrumental records. Imperial, on Darla Records, represents his solo approach clearly: guitar loops, synthesizer textures, slow harmonic development, and the layering technique he developed with the Cocteau Twins and brought to Lush's Spooky. Following the 4AD catalogue into Guthrie's solo work is one of the more direct threads available to a collector moving outward from the label."
    }
  ]$json$,
  'Heaven or Las Vegas'
);
